/* Contact atelier — a complete, browser-local conversation prototype. No network requests or persistent personal data. */
const Z_PATHS={
 product:{label:'Uma ideia de produto',title:'Uma ideia merece espaço.',reply:'Vamos começar pelo que você imagina.',question:'Para quem você quer construir?',hint:'Conte quem usaria o produto e o que você gostaria de tornar mais simples.',examples:['Para clientes que precisam pedir crédito.','Para equipes que atendem pelo WhatsApp.','Ainda estou descobrindo.'],focus:'E o que faria essa ideia valer a pena?',choices:['Uma experiência mais simples','Um novo negócio','Menos trabalho manual','Quero explorar as possibilidades'],tags:['Produto','Experiência','Construção']},
 connect:{label:'Conectar o que já existe',title:'O próximo pode começar no que existe.',reply:'Não precisamos começar do zero.',question:'O que você quer aproximar?',hint:'Pode ser uma equipe, um sistema, um canal ou uma parte da operação que hoje trabalha separada.',examples:['Meu sistema e o atendimento ao cliente.','Dados que estão em lugares diferentes.','Uma operação manual e os nossos sistemas.'],focus:'Onde essa conexão faria mais diferença?',choices:['No dia a dia da equipe','Na experiência do cliente','Na velocidade da operação','Quero entender por onde começar'],tags:['Integração','Operação','Continuidade']},
 discover:{label:'Conhecer a Catalisa',title:'Conhecer também é um começo.',reply:'Vamos encontrar um bom ponto de entrada.',question:'O que despertou sua curiosidade?',hint:'Você pode trazer uma pergunta de negócio, uma dúvida sobre a plataforma ou apenas uma vontade de explorar.',examples:['Como a plataforma funciona na prática.','O que consigo construir com os Building Blocks.','Como usar com os sistemas que já tenho.'],focus:'Qual caminho você gostaria de explorar primeiro?',choices:['Ver um exemplo aplicado','Entender a arquitetura','Conversar sobre meu contexto','Ainda não sei'],tags:['Plataforma','Possibilidades','Conversa']},
 partner:{label:'Uma parceria',title:'Boas conexões abrem caminhos.',reply:'Vamos entender o que podemos aproximar.',question:'Que encontro você tem em mente?',hint:'Conte um pouco sobre o que você faz e onde imagina uma conexão com a Catalisa.',examples:['Levar a plataforma para nossos clientes.','Combinar nossa solução com a Catalisa.','Explorar um projeto em conjunto.'],focus:'O que você gostaria de construir junto?',choices:['Uma oferta para o mercado','Uma integração de produtos','Uma oportunidade em comum','Vamos descobrir na conversa'],tags:['Parceria','Complementaridade','Possibilidades']},
 custom:{label:'Uma nova conversa',title:'Todo começo tem seu próprio caminho.',reply:'Tem espaço para essa conversa aqui.',question:'O que seria importante entendermos?',hint:'Conte o contexto que ajudaria uma pessoa da Catalisa a chegar mais preparada à conversa.',examples:['O que acontece hoje e o que quero mudar.','Para quem estou pensando nessa ideia.','Prefiro entender junto com vocês.'],focus:'O que você espera dessa primeira conversa?',choices:['Encontrar uma direção','Explorar possibilidades','Tirar uma dúvida','Conhecer a equipe'],tags:['Contexto','Intenção','Conversa']}
};
function zEsc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function zArt(){return `<svg class="z-art" viewBox="0 0 620 650" role="img" aria-label="Peças geométricas se aproximam e formam uma passagem: uma conversa encontra sua forma."><defs><linearGradient id="z-purple" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b598ce"/><stop offset="1" stop-color="#79519e"/></linearGradient><linearGradient id="z-orange" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ffc18e"/><stop offset="1" stop-color="#e88e4f"/></linearGradient><linearGradient id="z-stone" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#eee4f4"/><stop offset="1" stop-color="#c8b2dc"/></linearGradient><filter id="z-shadow"><feGaussianBlur stdDeviation="17"/></filter></defs><circle class="z-halo" cx="322" cy="286" r="213" fill="#e8deef"/><g class="z-grid" fill="none" stroke="#b5a5bc" stroke-width=".65"><path d="M37 463L306 308L577 464L308 620Z"/><path d="M91 494L360 339M145 526L414 370M199 557L468 401M253 588L522 432M91 432L361 588M145 401L415 557M199 370L469 526M253 339L523 495" stroke-dasharray="2 8"/></g><ellipse cx="315" cy="505" rx="180" ry="31" fill="#614071" opacity=".14" filter="url(#z-shadow)"/><g class="z-plinth"><path d="M119 456L306 348L493 456L306 564Z" fill="#e6d9ed"/><path d="M119 456V474L306 582V564Z" fill="#c5add7"/><path d="M306 564L493 456V474L306 582Z" fill="#a98bbf"/><path d="M167 455L306 375L445 455L306 535Z" fill="none" stroke="#b69bc8" stroke-width=".7"/></g><path class="z-connector" d="M153 307L251 363L357 302L452 356" fill="none" stroke="#b493cc" stroke-width="1.5" stroke-dasharray="4 7"/><g class="z-piece z-piece-a"><path d="M202 309L234 291L267 310V432L235 451L202 432Z" fill="url(#z-purple)"/><path d="M235 328L267 310V432L235 451Z" fill="#724a94"/><path d="M202 309L234 291L267 310L235 328Z" fill="#cfb9e1"/></g><g class="z-piece z-piece-b"><path d="M345 309L377 291L410 310V432L378 451L345 432Z" fill="url(#z-purple)"/><path d="M378 328L410 310V432L378 451Z" fill="#724a94"/><path d="M345 309L377 291L410 310L378 328Z" fill="#cfb9e1"/></g><g class="z-piece z-piece-c"><path d="M188 281L221 262L425 279L392 298Z" fill="#ffd0a7"/><path d="M188 281V321L392 338V298Z" fill="url(#z-orange)"/><path d="M392 298L425 279V319L392 338Z" fill="#d97c41"/></g><g class="z-piece z-piece-d"><ellipse cx="308" cy="415" rx="45" ry="25" fill="#9a79b4"/><path d="M263 402V415C263 448 353 448 353 415V402Z" fill="#b799cd"/><ellipse cx="308" cy="402" rx="45" ry="25" fill="url(#z-stone)"/><circle cx="308" cy="401" r="10" fill="#f8d874"/></g><g class="z-sun"><circle cx="450" cy="180" r="26" fill="#f3c46d"/><circle cx="450" cy="180" r="37" fill="none" stroke="#dbbd7d" stroke-width=".6"/></g><g class="z-small-dot"><circle cx="125" cy="250" r="7" fill="#9167ac"/><circle cx="491" cy="389" r="4" fill="#e5985a"/></g><g class="z-art-guides" fill="none" stroke="#c0a9d0" stroke-width=".7"><path d="M71 180H130M100 150V210M484 515H543M513 485V545"/><circle cx="100" cy="180" r="12"/><path d="M78 562H157M78 568H122"/></g></svg>`;}
function zInitial(){return {step:'intro',path:'custom',idea:'',context:'',focus:'',name:'',channel:'',address:'',editing:false,history:[],drafts:{},paused:false,identity:{contactId:null,leadId:null,createdAt:null},demo:{generated:false,tab:'product',screen:0,selection:'',human:false,device:'both',flowIndex:-1,running:false,refinements:[],reply:'',draft:'',progress:0,handoffRequested:false,consent:false,assumed:false}};}
function zPage(){return `<div class="z-page" id="z-page" data-scene="open"><section class="z-conversation wrap" aria-label="Uma conversa com a Catalisa"><div class="z-topline"><span>CATALISA / CONTATO</span><button data-z="about" class="z-prototype">Protótipo interativo <span>↗</span></button></div><div class="z-stage"><div class="z-dialogue" id="z-dialogue">${zView(zInitial())}</div><aside class="z-visual" aria-label="A conversa encontra uma forma"><div class="z-art-counter"><span id="z-art-index">01 — PEÇAS EM ABERTO</span><span>ESTUDO DE CONEXÃO</span></div>${zArt()}<div class="z-visual-caption"><span class="z-caption-line"></span><p id="z-art-caption">O próximo ainda<br>pode ter muitas formas.</p><button data-z="motion" aria-label="Pausar movimento" aria-pressed="false">Ⅱ</button></div><div class="z-art-tags" id="z-art-tags"><span>Uma intenção.</span><span>Infinitas conexões.</span></div></aside></div><div id="z-demo" hidden></div><div class="z-bottomline"><ol class="z-progress" aria-label="Momentos da conversa"><li data-z-phase="0" aria-current="step"><span>01</span> Conversar</li><li data-z-phase="1"><span>02</span> Dar forma</li><li data-z-phase="2"><span>03</span> Explorar e continuar</li></ol><button data-z="history" id="z-history-button" hidden>Ver nossa conversa <span>↗</span></button></div></section><section class="z-alternative wrap"><div><span class="z-eyebrow">OUTROS PONTOS DE PARTIDA</span><h2>Você escolhe<br>por onde chegar.</h2></div><div class="z-alternative-links"><button data-z="direct"><span>Prefiro falar direto com a equipe</span><i>↗</i></button><a href="/lab/"><span>Quero primeiro imaginar um produto</span><i>↗</i></a><a href="https://docs.catalisa.app/" target="_blank" rel="noopener noreferrer"><span>Estou procurando a documentação</span><i>↗</i></a></div></section><dialog id="z-dialog" class="z-modal" aria-labelledby="z-dialog-title"><div id="z-dialog-content"></div></dialog></div>`;}
function zEntry(s,{label,placeholder,value='',type='text',max=1200,button='Continuar',optional=false}){return `<form id="z-entry" novalidate><label class="sr-only" for="z-input">${label}</label><div class="z-input-row">${type==='textarea'?`<textarea id="z-input" rows="2" maxlength="${max}" placeholder="${placeholder}" aria-describedby="z-input-help z-input-error">${zEsc(value)}</textarea>`:`<input id="z-input" type="${type}" maxlength="${max}" value="${zEsc(value)}" placeholder="${placeholder}" ${s.step==='name'?'autocomplete="name"':s.channel==='email'&&s.step==='address'?'autocomplete="email"':s.channel==='whatsapp'&&s.step==='address'?'autocomplete="tel"':'autocomplete="off"'} aria-describedby="z-input-help z-input-error">`}<button class="z-send" type="submit" aria-label="${button}"><span aria-hidden="true">↗</span></button></div><div class="z-input-meta"><span id="z-input-help">${s.step==='intro'||s.step==='context'?'Escreva livremente e use ↗. Ou clique numa sugestão para responder.':button}</span>${optional?'<button type="button" data-z="skip">Podemos descobrir juntos ↗</button>':''}</div><p id="z-input-error" class="z-error" role="status"></p></form>`;}
function zBack(s){return s.step==='intro'?'':`<button class="z-back" data-z="back"><span aria-hidden="true">←</span> ${s.editing?'Voltar ao resumo':'Voltar um passo'}</button>`;}
function zView(s){const p=Z_PATHS[s.path];let body='';
 if(s.step==='intro')body=`<span class="z-kicker">UMA CONVERSA. UM COMEÇO.</span><h1 id="z-title" tabindex="-1">Vamos dar forma<br>à próxima<br><em>conversa.</em></h1><p class="z-lead">Conte sua ideia com suas palavras.<br>Depois, vamos explorar uma primeira forma do seu produto.</p><span class="zd-question">O que você gostaria de construir ou transformar?</span>${zEntry(s,{label:'O que você gostaria de colocar em movimento?',placeholder:'Ex.: agendamento por WhatsApp para minha clínica.',type:'textarea',value:s.drafts.intro||''})}<div class="z-starts"><span>OU ESCOLHA UM PONTO DE PARTIDA</span><div>${Object.entries(Z_PATHS).filter(([k])=>k!=='custom').map(([k,v])=>`<button data-z-path="${k}">${v.label}<i>↗</i></button>`).join('')}</div></div>`;
 if(s.step==='context')body=`${zBack(s)}<span class="z-kicker">${zEsc(p.reply)}</span><h1 id="z-title" tabindex="-1">${p.question}</h1><p class="z-lead">${p.hint}</p>${zEntry(s,{label:p.question,placeholder:'Conte um pouco do seu contexto…',type:'textarea',value:s.drafts.context??s.context,optional:true})}<div class="z-examples"><span>PODE ESCREVER LIVREMENTE OU USAR UM EXEMPLO</span>${p.examples.map(x=>`<button data-z-answer="${zEsc(x)}">${x}<i>↗</i></button>`).join('')}</div>`;
 if(s.step==='focus')body=`${zBack(s)}<span class="z-kicker">JÁ TEMOS UM PONTO DE PARTIDA.</span><h1 id="z-title" tabindex="-1">${p.focus}</h1><p class="z-lead">Escolha uma sugestão abaixo ou escreva livremente.<br>Não existe uma resposta certa.</p><div class="z-directions">${p.choices.map((x,i)=>`<button data-z-answer="${zEsc(x)}"><span>0${i+1}</span>${x}<i>↗</i></button>`).join('')}</div>${zEntry(s,{label:p.focus,placeholder:'Para mim, o mais importante é…',value:s.drafts.focus??s.focus,max:500})}`;
 if(s.step==='summary')body=`${zBack(s)}<span class="z-kicker">${s.name?"PRAZER, "+zEsc(s.name.toLocaleUpperCase('pt-BR'))+". ":""}PODEMOS PARTIR DAQUI.</span><h1 id="z-title" tabindex="-1" class="z-title-compact">A conversa já tem<br><em>uma direção.</em></h1><p class="z-lead">Veja se entendemos seu ponto de partida.<br>Você pode ajustar o que quiser. A seguir, vamos abrir uma demo conceitual.</p><div class="z-brief"><div><span>O QUE MOVE A CONVERSA</span><button data-z-edit="intro" aria-label="Editar o motivo da conversa">Editar ↗</button><p>${zEsc(s.idea)}</p></div><div><span>O CONTEXTO</span><button data-z-edit="context" aria-label="Editar o contexto">Editar ↗</button><p>${zEsc(s.context||'Para descobrir juntos na conversa.')}</p></div><div><span>A DIREÇÃO</span><button data-z-edit="focus" aria-label="Editar a direção">Editar ↗</button><p>${zEsc(s.focus||'Uma conversa aberta com a equipe.')}</p></div></div><button class="z-primary" data-z="continue">Visualizar meu produto <span>↗</span></button>`;
 if(s.step==='name')body=`${zBack(s)}<span class="z-kicker">AGORA, VAMOS APROXIMAR AS PESSOAS.</span><h1 id="z-title" tabindex="-1">Como podemos<br>chamar <em>você?</em></h1><p class="z-lead">Antes de dar forma à sua ideia,<br>como podemos chamar você durante a conversa?</p>${zEntry(s,{label:'Como podemos chamar você?',placeholder:'Seu nome',value:s.drafts.name??s.name,max:100})}<p class="z-quiet">Para experimentar, você pode usar um nome fictício.</p>`;
 if(s.step==='channel')body=`${zBack(s)}<span class="z-kicker">PRAZER, ${zEsc(s.name.toLocaleUpperCase('pt-BR'))}.</span><h1 id="z-title" tabindex="-1">Como você prefere<br><em>continuar?</em></h1><p class="z-lead">Escolha onde essa conversa faria<br>mais sentido para você.</p><div class="z-channels"><button data-z-channel="here"><span class="z-channel-symbol">c.</span><span>Aqui na página<small>Continuar do conceito para o atendimento.</small></span><i>↗</i></button><button data-z-channel="email"><span class="z-channel-symbol">@</span><span>Por e-mail<small>Para continuar no seu tempo.</small></span><i>↗</i></button><button data-z-channel="whatsapp"><span class="z-channel-symbol">↗</span><span>Pelo WhatsApp<small>Para uma troca mais próxima.</small></span><i>↗</i></button><button data-z-channel="explore" class="z-explore-only">Voltar a explorar o conceito <i>↗</i></button></div><p class="z-quiet">Esta é uma demonstração. Nenhuma mensagem será enviada.</p>`;
 if(s.step==='address')body=`${zBack(s)}<span class="z-kicker">${s.channel==='email'?'UMA CONVERSA QUE PODE CONTINUAR.':'VAMOS MANTER A CONEXÃO.'}</span><h1 id="z-title" tabindex="-1">${s.channel==='email'?'Em qual <em>e-mail?</em>':'Qual é o seu<br><em>WhatsApp?</em>'}</h1><p class="z-lead">Na experiência final, este seria o canal<br>para a equipe continuar com você.</p>${zEntry(s,{label:s.channel==='email'?'Seu e-mail':'Seu WhatsApp com DDD e país',placeholder:s.channel==='email'?'voce@empresa.com':'+55 (11) 99999-9999',type:s.channel==='email'?'email':'tel',value:s.drafts.address??s.address,max:200,button:'Preparar encaminhamento'})}<p class="z-quiet">Pode usar um contato fictício. Nada é enviado ou salvo. Recarregar a página reinicia a conversa.</p><button class="z-text-action" data-z-channel="here">Prefiro continuar aqui na página ↗</button>`;
 if(s.step==='intro')body+='<button class="zd-sample-start" data-z="sample">Quer ver primeiro? Explore uma conversa de exemplo ↗</button>';
 if(s.step==='preparing')body=`${zBack(s)}<span class="z-kicker">SUA CONVERSA VIRA UM CONCEITO</span><h1 id="z-title" tabindex="-1">As peças começam<br>a <em>se encontrar.</em></h1><p class="z-lead">Estamos mostrando como seria a passagem da conversa para uma primeira demo do produto.</p><ol class="zd-preparing">${['Organizar o que você contou','Compor telas, peças e jornada','Abrir uma primeira possibilidade'].map((x,i)=>`<li class="${s.demo.progress>=i?'active':''}"><span>${s.demo.progress>i?'✓':String(i+1).padStart(2,'0')}</span>${x}</li>`).join('')}</ol><p class="z-quiet">Preparação visual simulada. Nenhuma IA está sendo chamada.</p><button data-z="show-now" class="z-text-action">Abrir prévia agora ↗</button>`;
 if(s.step==='confirm')body=`${zBack(s)}<span class="z-kicker">VOCÊ ESCOLHE O PRÓXIMO PASSO</span><h1 id="z-title" tabindex="-1">Vamos levar<br><em>o contexto junto?</em></h1><p class="z-lead">A equipe receberia sua conversa${s.demo.generated?', a prévia do produto e os ajustes que você pediu':''}. Assim, a próxima conversa começa de onde você chegou.</p><div class="zd-confirm-packet"><span>CONTINUIDADE</span><strong>${zEsc(s.name)} · ${s.channel==='here'?'aqui na página':s.channel==='email'?'e-mail':'WhatsApp'}</strong>${s.address?`<small>${zEsc(s.address)}</small>`:''}<p>${zEsc(s.idea)}</p></div><label class="zd-consent"><input id="z-share-context" type="checkbox" ${s.demo.consent?'checked':''}><span>Quero continuar com a equipe e levar a conversa${s.demo.generated?' e a prévia':''} junto.</span></label><button class="z-primary" data-z="confirm-handoff" ${s.demo.consent?'':'disabled'}>Simular encaminhamento <span>↗</span></button><p class="z-quiet">Esta confirmação faz parte do protótipo. Nada será enviado.</p>`;
 return `<div class="z-view z-view-${s.step}">${body}</div>`;
}
const zPreviousPage=cPage;cPage=function(route,blocks){return route==='/contato/'?zPage():zPreviousPage(route,blocks)};
function zBind(){const page=document.getElementById('z-page');if(!page)return;let s=zInitial(),lastFocus=null,generation=0,flowRun=0;
 const phase=()=>s.step==='intro'?0:['context','focus','summary','preparing'].includes(s.step)?1:2;
 const full=()=>['preview','handoff'].includes(s.step);
 const scene=()=>s.step==='intro'?'open':s.step==='context'?'approach':s.step==='focus'?'align':['done','handoff'].includes(s.step)?'complete':'connected';
 const remember=()=>{const input=document.getElementById('z-input');if(input)s.drafts[s.step]=input.value;};
 function render(focus=true){page.dataset.scene=scene();page.dataset.path=s.path;page.dataset.mode=full()?'demo':'conversation';page.classList.toggle('z-paused',s.paused);page.querySelector('.z-stage').hidden=full();document.getElementById('z-dialogue').innerHTML=full()?'':zView(s);const output=document.getElementById('z-demo');output.hidden=!full();output.innerHTML=s.step==='preview'?zdView(s):s.step==='handoff'?zdHandoff(s):'';document.getElementById('z-art-index').textContent=['01 — PEÇAS EM ABERTO','02 — ENCONTRANDO CONTEXTO','03 — UM CAMINHO EM COMUM'][phase()];document.getElementById('z-art-caption').innerHTML=phase()===0?'O próximo ainda<br>pode ter muitas formas.':phase()===1?'Sua ideia começa<br>a encontrar uma forma.':'Uma conversa.<br>Vários próximos passos.';document.getElementById('z-art-tags').innerHTML=(phase()===0?['Uma intenção.','Infinitas conexões.']:Z_PATHS[s.path].tags).map(t=>`<span>${zEsc(t)}</span>`).join('');page.querySelectorAll('[data-z-phase]').forEach(el=>{const active=Number(el.dataset.zPhase)===phase();if(active)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');el.classList.toggle('z-phase-done',Number(el.dataset.zPhase)<phase());});document.getElementById('z-history-button').hidden=!s.idea;const motion=page.querySelector('[data-z="motion"]');motion.setAttribute('aria-pressed',String(s.paused));motion.setAttribute('aria-label',s.paused?'Retomar movimento':'Pausar movimento');motion.textContent=s.paused?'▷':'Ⅱ';if(focus){document.getElementById('z-title')?.focus({preventScroll:true});if(page.getBoundingClientRect().top<-160)page.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}
 function refresh(selector){render(false);if(selector)page.querySelector(selector)?.focus({preventScroll:true});}
 function record(question,answer){const found=s.history.findIndex(x=>x.step===s.step);const item={step:s.step,question,answer};if(found<0)s.history.push(item);else s.history[found]=item;}
 function identify(text){if(/parcer|junt[oa]s?|oferta|revend/i.test(text))return'partner';if(/integr|conect|legad|já (tenho|existe)|sistema existente/i.test(text))return'connect';if(/conhecer|entender a (catalisa|plataforma)|como funciona/i.test(text))return'discover';if(/produto|constru|criar|ideia|aplicativo|app\b/i.test(text))return'product';return'custom';}
 function invalidate(){s.demo.reply='';s.demo.generated=false;s.demo.screen=0;s.demo.selection='';s.demo.flowIndex=-1;s.demo.assumed=false;s.demo.consent=false;generation++;flowRun++;}
 function advance(answer){answer=String(answer||'').trim();const error=document.getElementById('z-input-error');const fail=message=>{if(error)error.textContent=message;document.getElementById('z-input')?.setAttribute('aria-invalid','true');};
  if(s.step==='intro'){if(answer.length<3)return fail('Escreva uma frase com sua ideia, ou escolha uma sugestão abaixo.');s.drafts.intro=answer;s.idea=answer;s.path=identify(answer);record('O que você gostaria de colocar em movimento?',answer);invalidate();s.step=s.editing?'summary':'context';}
  else if(s.step==='context'){if(answer.length<3)return fail('Pode responder com suas palavras. Uma frase já ajuda.');s.drafts.context=answer;s.context=answer;record(Z_PATHS[s.path].question,answer);invalidate();s.step=s.editing?'summary':'focus';}
  else if(s.step==='focus'){if(answer.length<2)return fail('Escolha uma sugestão ou escreva livremente o que você espera.');s.drafts.focus=answer;s.focus=answer;record(Z_PATHS[s.path].focus,answer);invalidate();s.step=s.name?'summary':'name';}
  else if(s.step==='name'){if(answer.length<2)return fail('Digite pelo menos duas letras. Pode usar um nome fictício.');s.drafts.name=answer;s.name=answer;record('Como podemos chamar você?',answer);if(!s.identity.contactId){const id=Date.now().toString(36);s.identity={contactId:'mock-contact-'+id,leadId:'mock-lead-'+id,createdAt:new Date().toISOString()};}s.step=s.demo.handoffRequested?'channel':'summary';}
  else if(s.step==='address'){if(s.channel==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(answer))return fail('Confira o e-mail. Por exemplo: voce@empresa.com.');if(s.channel==='whatsapp'&&(!/^\+?[\d\s().-]+$/.test(answer)||answer.replace(/\D/g,'').length<10||answer.replace(/\D/g,'').length>15))return fail('Confira o número: inclua o DDD e entre 10 e 15 dígitos.');s.drafts.address=answer;s.address=answer;record(s.channel==='email'?'Em qual e-mail?':'Qual é o seu WhatsApp?',answer);s.step='confirm';}
  s.editing=false;render();
 }
 function build(){if(!s.name){s.step='name';render();return;}const token=++generation;s.step='preparing';s.demo.progress=0;render();[450,950,1500].forEach((ms,i)=>setTimeout(()=>{if(token!==generation||s.step!=='preparing')return;if(i===2){s.demo.generated=true;s.step='preview';s.demo.tab='product';s.demo.screen=0;render();}else{s.demo.progress=i+1;render(false);}},ms));}
 const transcript=()=>['CATALISA / CONVERSA E CONCEITO','Demonstração local. Nenhuma mensagem foi enviada.','',...s.history.flatMap(x=>[x.question,x.answer,'']),s.demo.generated?'CONCEITO PROPOSTO\n'+JSON.stringify(zdBrief(s),null,2):'Sem conceito gerado nesta conversa.'].join('\n');
 function closeDialog(){const d=document.getElementById('z-dialog');if(d.open)d.close();}
 function openDialog(type){lastFocus=document.activeElement;const dialog=document.getElementById('z-dialog');document.getElementById('z-dialog-content').innerHTML=`<div class="z-modal-top"><span>CATALISA / ${type==='history'?'NOSSA CONVERSA':type==='examples'?'OUTROS EXEMPLOS':'SOBRE ESTA EXPERIÊNCIA'}</span><button data-z="close" aria-label="Fechar janela">×</button></div>${type==='history'?`<h2 id="z-dialog-title">O caminho até aqui.</h2><p>Seu ponto de partida e os ajustes acompanham o conceito.</p><ol class="z-history">${s.history.map(x=>`<li><span>Catalisa</span><h3>${zEsc(x.question)}</h3><span>Você</span><p>${zEsc(x.answer)}</p>${['intro','context','focus'].includes(x.step)?`<button data-z-edit="${x.step}">Editar esta resposta ↗</button>`:''}</li>`).join('')||'<li>A conversa ainda está começando.</li>'}${s.demo.refinements.map(x=>`<li><span>Ajuste pedido</span><p>${zEsc(x)}</p></li>`).join('')}</ol><button class="z-primary" data-z="close">Continuar de onde parei <span>↗</span></button>`:type==='examples'?`<h2 id="z-dialog-title">Outras ideias.<br>Outras formas.</h2><p>Estes exemplos substituem o ponto de partida atual. Nenhum dado é enviado.</p><div class="zd-samples">${Object.entries(ZD_CASES).map(([key,d])=>`<button data-zd-sample="${key}"><span>${zEsc(d.name)}</span><p>${zEsc(d.placeholder)}</p><i>↗</i></button>`).join('')}</div>`:`<h2 id="z-dialog-title">Da conversa<br>a uma primeira forma.</h2><p>Responda com suas palavras ou use as sugestões. Em seguida, explore um conceito com telas clicáveis, peças e jornada, antes de escolher se quer continuar com a equipe.</p><div class="z-modal-note">Esta versão usa modelos locais de clínica, crédito, recrutamento, comércio e atendimento. Os ajustes demonstrados são revisão humana, formato de aplicativo e explicação das peças. Não há IA, fila ou atendente conectado. Nada é transmitido ou salvo; recarregar reinicia a experiência.</div><button class="z-primary" data-z="close">Quero experimentar <span>↗</span></button>`}`;dialog.showModal();}
 function refine(text){text=text.trim();if(text.length<3){document.getElementById('zd-refine-status').textContent='Conte o ajuste em uma frase, ou use as sugestões acima.';return;}s.demo.refinements.push(text);s.demo.draft='';if(/human|pessoa|revis|aprova/.test(text.toLowerCase())){s.demo.human=!/sem revis|remov|tirar|sem human/.test(text.toLowerCase());s.demo.tab='flow';s.demo.flowIndex=-1;s.demo.reply=s.demo.human?'Incluí uma revisão por uma pessoa antes do último passo. Veja onde ela entra na jornada. As telas também passam a indicar essa revisão.':'Removi a revisão adicional da composição. As responsabilidades que já pertencem à equipe, como seleção de candidatos, continuam humanas.';}else if(/app|aplicativo|celular|mobile/.test(text.toLowerCase())){s.demo.device='phone';s.demo.tab='product';s.demo.reply='Trouxe o conceito para o aplicativo. Experimente o botão da tela para percorrer os três momentos.';}else if(/peça|bloco|building|arquitet|explic/.test(text.toLowerCase())){s.demo.tab='blocks';s.demo.reply='Cada peça cuida de uma responsabilidade. O canal leva a conversa; as capacidades organizam dados e ações. A jornada conecta essas responsabilidades na ordem certa.';}else{s.demo.reply='Anotei esse pedido junto ao conceito para a equipe aprofundar. Esta versão demonstra visualmente revisão humana e aplicativo; outros ajustes ficam registrados, sem fingir uma geração que ainda não está conectada.';}refresh('#zd-refine');}
 page.addEventListener('input',e=>{if(e.target.id==='zd-refine')s.demo.draft=e.target.value;});
 page.addEventListener('change',e=>{if(e.target.id==='z-share-context'){s.demo.consent=e.target.checked;page.querySelector('[data-z="confirm-handoff"]').disabled=!s.demo.consent;}});
 page.addEventListener('keydown',e=>{const tab=e.target.closest('[data-zd-tab]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const keys=['product','blocks','flow'];let i=keys.indexOf(tab.dataset.zdTab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;s.demo.tab=keys[i];flowRun++;s.demo.running=false;refresh('#zd-tab-'+keys[i]);});
 page.addEventListener('submit',e=>{if(e.target.id==='zd-refine-form'){e.preventDefault();refine(document.getElementById('zd-refine').value);return;}if(e.target.id!=='z-entry')return;e.preventDefault();remember();advance(document.getElementById('z-input').value);});
 page.addEventListener('click',async e=>{const sample=e.target.closest('[data-zd-sample]'),dt=e.target.closest('[data-zd-tab]'),screen=e.target.closest('[data-zd-screen]'),choice=e.target.closest('[data-zd-choice]'),device=e.target.closest('[data-zd-device]'),node=e.target.closest('[data-zd-node]'),da=e.target.closest('[data-zd]');
  if(sample){closeDialog();flowRun++;const person={name:s.name,identity:s.identity};s=zInitial();s.name=person.name;s.identity=person.identity;const d=ZD_CASES[sample.dataset.zdSample];s.idea=d.placeholder;s.context=d.audience;s.focus='Uma experiência mais simples';s.path='product';s.history=[{step:'intro',question:'Ideia de exemplo',answer:s.idea},{step:'context',question:'Para quem?',answer:s.context},{step:'focus',question:'O que esperamos melhorar?',answer:s.focus}];if(s.name)s.history.push({step:'name',question:'Como podemos chamar você?',answer:s.name});s.step=s.name?'summary':'name';render();return;}
  if(dt){s.demo.tab=dt.dataset.zdTab;flowRun++;s.demo.running=false;refresh('#zd-tab-'+s.demo.tab);return;}
  if(screen){s.demo.screen=Number(screen.dataset.zdScreen);refresh('.zd-app-content h3');return;}
  if(choice){s.demo.selection=zdConcept(s).options[Number(choice.dataset.zdChoice)];refresh('[data-zd-choice="'+choice.dataset.zdChoice+'"]');return;}
  if(device){s.demo.device=device.dataset.zdDevice;refresh('[data-zd-device="'+s.demo.device+'"]');return;}
  if(node){s.demo.flowIndex=Number(node.dataset.zdNode);flowRun++;s.demo.running=false;refresh('[data-zd-node="'+s.demo.flowIndex+'"]');return;}
  if(da){const a=da.dataset.zd;if(a==='human')refine(s.demo.human?'Remover revisão humana adicional':'Incluir revisão humana');if(a==='app')refine('Ver como aplicativo');if(a==='explain')refine('Me explique as peças');if(a==='review'){s.demo.handoffRequested=false;s.step='summary';render();}if(a==='handoff'){flowRun++;s.demo.running=false;s.demo.handoffRequested=true;s.demo.consent=false;s.step=s.name?'channel':'name';render();}if(a==='return-demo'){s.step=s.demo.generated?'preview':'summary';render();}if(a==='assume'){s.demo.assumed=true;render();}if(a==='sample')openDialog('examples');if(a==='play'){const token=++flowRun;const d=zdConcept(s),count=zdJourney(s,d).length;s.demo.running=true;s.demo.flowIndex=0;refresh('[data-zd="play"]');for(let i=1;i<=count;i++)setTimeout(()=>{if(token!==flowRun||s.step!=='preview'||s.demo.tab!=='flow')return;s.demo.flowIndex=i;if(i===count){s.demo.running=false;s.demo.reply='O percurso chegou ao próximo passo. Na versão conectada, cada etapa teria seu contexto e resultado; aqui você está vendo uma simulação visual.';}refresh();},i*650);}return;}
  const path=e.target.closest('[data-z-path]'),answer=e.target.closest('[data-z-answer]'),edit=e.target.closest('[data-z-edit]'),channel=e.target.closest('[data-z-channel]'),action=e.target.closest('[data-z]');
  if(path){remember();s.path=path.dataset.zPath;s.idea=Z_PATHS[s.path].label;s.drafts.intro=s.idea;record('O que você gostaria de colocar em movimento?',s.idea);invalidate();s.step=s.editing?'summary':'context';s.editing=false;render();return;}
  if(answer){remember();advance(answer.dataset.zAnswer);return;}
  if(edit){closeDialog();s.step=edit.dataset.zEdit;s.editing=true;if(s.step==='intro')s.drafts.intro=s.idea;render();return;}
  if(channel){s.channel=channel.dataset.zChannel;s.address='';delete s.drafts.address;s.history=s.history.filter(x=>x.step!=='address'&&x.step!=='channel');s.history.push({step:'channel',question:'Como você prefere continuar?',answer:s.channel==='here'?'Aqui na página':s.channel==='email'?'Por e-mail':s.channel==='whatsapp'?'Pelo WhatsApp':'Continuar explorando'});s.step=s.channel==='explore'?(s.demo.generated?'preview':'summary'):s.channel==='here'?'confirm':'address';render();return;}
  if(!action)return;const a=action.dataset.z;
  if(a==='back'){remember();generation++;if(s.editing){s.editing=false;s.step='summary';}else s.step=({context:'intro',focus:'context',summary:'name',preparing:'summary',name:s.demo.generated?'preview':'focus',channel:s.demo.generated?'preview':'name',address:'channel',confirm:s.channel==='here'?'channel':'address'})[s.step]||'intro';render();}
  if(a==='continue')build();
  if(a==='show-now'&&s.name){generation++;s.demo.generated=true;s.step='preview';render();}
  if(a==='sample'){openDialog('examples');}
  if(a==='skip')advance('Para descobrir juntos na conversa.');
  if(a==='direct'){remember();if(!s.idea){s.idea='Falar diretamente com a equipe';s.context='Conversa aberta, sem contexto adicional neste momento.';s.focus='Conhecer a equipe e combinar o próximo passo.';s.path='custom';s.history=[{step:'intro',question:'O que você gostaria de colocar em movimento?',answer:s.idea}];}s.demo.handoffRequested=true;s.demo.consent=false;s.editing=false;s.step=s.name?'channel':'name';render();page.scrollIntoView({behavior:'smooth'});}
  if(a==='confirm-handoff'&&s.demo.consent){s.step='handoff';render();}
  if(a==='motion'){remember();s.paused=!s.paused;render(false);}
  if(a==='history'||a==='about')openDialog(a);
  if(a==='close')closeDialog();
  if(a==='restart'){generation++;flowRun++;s=zInitial();render();}
  if(a==='download'){const blob=new Blob([transcript()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='catalisa-conversa-e-conceito.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);page.querySelector('.z-copy-status').textContent='Conversa e conceito preparados para download.';}
 });
 document.getElementById('z-dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});});
 document.getElementById('z-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',zBind);
